logger = logging.getLogger(__name__)

KERNEL_MODE = 1
TILE_BUDGET = 16384
BLOCK_M_CAP = 2048
NUM_WARPS = 8
LOOP_STAGES = 1
LAUNCH_STAGES = 2
WELFORD_MODE = 1
