@libentry()
@triton.jit(do_not_specialize=["batch_dim", "spatial_dim", "eps"])
def _nbn_no_stats_out_kernel(
    input_pointer,
    weight_pointer,
    bias_pointer,
    mean_pointer,
    inv_std_pointer,
    output_pointer,
    batch_dim,
    spatial_dim,
    input_batch_stride,
    input_feat_stride,
    input_spatial_stride,
    output_batch_stride,
    output_feat_stride,
    output_spatial_stride,
    eps,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    LOOP_STAGES: tl.constexpr,
    WELFORD_MODE: tl.constexpr,
):
    """单 channel 单 CTA：第一遍统计均值方差，第二遍归一化写出。

    no_stats_out 没有持久化 running stats，因此专用 kernel 不需要训练分支里的
    running_mean/running_var 读写与动量更新；统计量始终以 fp32 累积。
    """
    feat_pid = tl.program_id(axis=0)
    first_moment = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    second_moment = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    element_count = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.int32)
    num_steps_m = tl.cdiv(batch_dim, BLOCK_M)
    num_steps_n = tl.cdiv(spatial_dim, BLOCK_N)
    num_elements = batch_dim * spatial_dim

    for m_step in tl.range(0, num_steps_m, num_stages=LOOP_STAGES):
        for n_step in range(0, num_steps_n):
            batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
            spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
            element_mask = (batch_offset[:, None] < batch_dim) & (
                spatial_offset[None, :] < spatial_dim
            )
            input_tile_pointer = (
                input_pointer
                + input_feat_stride * feat_pid
                + input_batch_stride * batch_offset[:, None]
                + input_spatial_stride * spatial_offset[None, :]
            )
            input_tile = tl.load(input_tile_pointer, mask=element_mask).to(tl.float32)
            step_index = m_step * num_steps_n + n_step + 1
            if WELFORD_MODE == 0:
                updated_mean = tl.where(
                    element_mask,
                    first_moment + (input_tile - first_moment) / step_index,
                    first_moment,
                )
                updated_second = tl.where(
                    element_mask,
                    second_moment
                    + (input_tile - updated_mean) * (input_tile - first_moment),
                    second_moment,
                )
            else:
                updated_mean = tl.where(
                    element_mask, first_moment + input_tile, first_moment
                )
                updated_second = tl.where(
                    element_mask,
                    second_moment + input_tile * input_tile,
                    second_moment,
                )
            element_count += element_mask.to(tl.int32)
            first_moment = updated_mean
            second_moment = updated_second

    if WELFORD_MODE == 0:
        final_mean = tl.sum(first_moment * element_count) / num_elements
        variance = (
            tl.sum(
                second_moment
                + element_count
                * (first_moment - final_mean)
                * (first_moment - final_mean)
            )
            / num_elements
        )
    else:
        final_mean = tl.sum(first_moment) / num_elements
        variance = tl.maximum(
            tl.sum(second_moment) / num_elements - final_mean * final_mean, 0.0
        )
    inv_std = 1.0 / tl.sqrt(variance + eps)
    tl.store(feat_pid + mean_pointer, final_mean)
    tl.store(feat_pid + inv_std_pointer, inv_std)

    if weight_pointer:
        weight = tl.load(feat_pid + weight_pointer).to(tl.float32)
    else:
        weight = 1.0
    if bias_pointer:
        bias = tl.load(feat_pid + bias_pointer).to(tl.float32)
    else:
        bias = 0.0

    for m_step in tl.range(0, num_steps_m, num_stages=LOOP_STAGES):
        for n_step in range(0, num_steps_n):
            batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
            spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
            element_mask = (batch_offset[:, None] < batch_dim) & (
                spatial_offset[None, :] < spatial_dim
            )
            input_tile_pointer = (
                input_pointer
                + input_feat_stride * feat_pid
                + input_batch_stride * batch_offset[:, None]
                + input_spatial_stride * spatial_offset[None, :]
            )
            output_tile_pointer = (
                output_pointer
                + output_feat_stride * feat_pid
                + output_batch_stride * batch_offset[:, None]
                + output_spatial_stride * spatial_offset[None, :]
            )
            input_tile = tl.load(input_tile_pointer, mask=element_mask).to(tl.float32)
            normalized = weight * (input_tile - final_mean) * inv_std + bias
            tl.store(output_tile_pointer, normalized, mask=element_mask)


def _choose_tile(batch_dim, spatial_dim):
    """按 2 的幂与元素预算选 tile；两条轴都至少 2 宽，避免 1 维切片布局崩溃。"""
    block_m = max(2, min(BLOCK_M_CAP, triton.next_power_of_2(batch_dim)))
    max_block_n = max(1, TILE_BUDGET // block_m)
    block_n = max(2, min(triton.next_power_of_2(spatial_dim), max_block_n))
    return block_m, triton.next_power_of_2(block_n)


def _native_batch_norm_legit(
    input: Tensor,
    weight,
    bias,
    running_mean: Tensor,
    running_var: Tensor,
    training: bool,
    momentum: float,
    eps: float,
):
    """Batch normalization with in-place running statistics updates."""
    logger.debug("GEMS _NATIVE_BATCH_NORM_LEGIT")
    output, save_mean, save_invstd = batch_norm(
        input,
        weight=weight,
        bias=bias,
        running_mean=running_mean,
        running_var=running_var,
        training=training,
        momentum=momentum,
        eps=eps,
    )
    return output, save_mean, save_invstd


def _native_batch_norm_legit_no_stats(
    input: Tensor,
    weight,
    bias,
    training: bool,
    momentum: float,
    eps: float,
):
    """Batch normalization without persistent running statistics."""
    logger.debug("GEMS _NATIVE_BATCH_NORM_LEGIT_NO_STATS")
    if not training:
        raise RuntimeError("Expected has_running_mean to be true, but got false.")
    channels = input.shape[1]
    running_mean = torch.zeros(channels, dtype=input.dtype, device=input.device)
    running_var = torch.ones(channels, dtype=input.dtype, device=input.device)
    return batch_norm(
        input,
        weight=weight,
        bias=bias,
        running_mean=running_mean,
        running_var=running_var,
        training=True,
        momentum=momentum,
        eps=eps,
    )


def _copy_outputs(result, out, save_mean, save_invstd):
    result_out, result_mean, result_invstd = result
    out.resize_as_(result_out).copy_(result_out)
    save_mean.resize_as_(result_mean).copy_(result_mean)
    save_invstd.resize_as_(result_invstd).copy_(result_invstd)
    return out, save_mean, save_invstd


